  A: PatternAThumbnail,
  B: PatternBThumbnail,
  C: PatternCThumbnail,
  D: PatternDThumbnail,
  E: PatternEThumbnail,
  F: PatternFThumbnail,
  G: PatternGThumbnail,
};

